// The client against the contract: every route it calls exists in `openapi.json` with that method, every operation of the
// contract is either called or declared as not called, and the generated files are the ones the server produces today.
import { readFileSync } from 'node:fs'
import openapiTS, { astToString } from 'openapi-typescript'
import { describe, expect, it } from 'vitest'
import { NOT_IN_CLIENT, operationKey, pathOf, routes, REQUEST_ERROR_CODES } from '../src/index.js'
// @ts-expect-error plain JavaScript without declarations
import { liveOpenapi, requestErrorCodes, serializeContract } from '../scripts/contract.mjs'

const contractText = readFileSync(new URL('../openapi.json', import.meta.url), 'utf8')
const contract = JSON.parse(contractText) as { paths: Record<string, Record<string, unknown>> }
const operations = Object.entries(contract.paths).flatMap(([path, item]) => Object.keys(item).filter((m) => m !== 'parameters').map((m) => `${m.toUpperCase()} ${path}`))

describe('routes against the contract', () => {
  it('every route of the client is an operation of the contract', () => {
    const missing = Object.values(routes).map(operationKey).filter((k) => !operations.includes(k))
    expect(missing).toEqual([])
  })

  it('every operation of the contract is called by the client or declared as not called, with its reason', () => {
    const called = new Set(Object.values(routes).map(operationKey))
    const neither = operations.filter((k) => !called.has(k) && !(k in NOT_IN_CLIENT))
    expect(neither).toEqual([])
    const stale = Object.keys(NOT_IN_CLIENT).filter((k) => !operations.includes(k) || called.has(k))
    expect(stale).toEqual([])
  })

  it('fills and encodes the parameters of a path, relative to the prefix', () => {
    expect(pathOf(routes.messageGet, { id: 'ab12' })).toBe('/messages/ab12')
    expect(pathOf(routes.replyEdit, { id: 'm1', replyId: 'r 2' })).toBe('/messages/m1/replies/r%202')
    expect(pathOf(routes.connectionCheck, { name: 'mi/gateway' })).toBe('/settings/connections/mi%2Fgateway/check')
    expect(() => pathOf(routes.messageGet)).toThrow(/needs the parameter/)
  })
})

describe('generated files', () => {
  it('openapi.json is the contract the server serves today', async () => {
    expect(serializeContract(await liveOpenapi())).toBe(contractText)
  })

  it('src/generated/schema.ts is what openapi-typescript makes of openapi.json', async () => {
    const ast = await openapiTS(contract as never)
    const expected = '// Generated by `npm run gen:client` from openapi.json (openapi-typescript). Do not edit.\n' + astToString(ast)
    expect(readFileSync(new URL('../src/generated/schema.ts', import.meta.url), 'utf8')).toBe(expected)
  })

  it('the error codes are the ones the sources of the server can answer with', () => {
    expect([...REQUEST_ERROR_CODES]).toEqual(requestErrorCodes())
  })
})
